// 统计
export const PEOPLE_COUNT = adlerPeople.length;
export const PEOPLE_PUBLIC_READY = adlerPeople.filter(p => p.reviewStatus === 'public_ready').length;

// seed 人物 ID 列表
export const SEED_PEOPLE_IDS = adlerPeople
  .filter(p => p.id.startsWith('person_seed_'))
  .map(p => p.id);

// 按 Lens 索引
export const peopleByLens: Record<string, PersonStory[]> = {};
adlerPeople.forEach(p => {
  if (p.reviewStatus !== 'public_ready') return;
  p.adlerianLensTags.forEach(lens => {
    if (!peopleByLens[lens]) peopleByLens[lens] = [];
    peopleByLens[lens].push(p);
  });
});

// 按 Pair 索引
export const peopleByPair: Record<string, PersonStory[]> = {};
adlerPeople.forEach(p => {
  if (p.reviewStatus !== 'public_ready') return;
  p.pairTags.forEach(pair => {
    if (!peopleByPair[pair]) peopleByPair[pair] = [];
    peopleByPair[pair].push(p);
  });
});

// 按场景索引
export const peopleByScene: Record<string, PersonStory[]> = {};
adlerPeople.forEach(p => {
  if (p.reviewStatus !== 'public_ready') return;
  p.contextTags.forEach(scene => {
    if (!peopleByScene[scene]) peopleByScene[scene] = [];
    peopleByScene[scene].push(p);
  });
});

// 按文化区域索引
export const peopleByCulture: Record<string, PersonStory[]> = {};
adlerPeople.forEach(p => {
  if (p.reviewStatus !== 'public_ready') return;
  if (!peopleByCulture[p.cultureRegion]) peopleByCulture[p.cultureRegion] = [];
  peopleByCulture[p.cultureRegion].push(p);
});

// Why You 检索算法
// 权重：profile 32% + pair 22% + current_life_task 16% + scene 10% +
//       culture/language 7% + age 5% + novelty 4% + opt-in identity 3% + editorial 1%
export function findMatchingPeople(
  profileScores: Record<string, number>,
  pairPatterns: string[],
  currentLifeTask: string,
  currentScene: string,
  cultureRegion?: string,
  ageGen?: string,
  optInIdentity?: string[],
  limit = 3,
  recentExposure?: string[],
): PersonStory[] {
  const exposed = new Set(recentExposure || []);

  const scored = adlerPeople
    .filter(p => p.reviewStatus === 'public_ready')
    .map(p => {
      let score = 0;

      // Profile 匹配 (32%)
      const dims = ['A', 'B', 'C', 'D'];
      const sortedDims = dims.sort((a, b) => (profileScores[b] || 0) - (profileScores[a] || 0));
      const top2 = sortedDims.slice(0, 2);
      // 简化：用 lens 标签近似维度匹配
      const lensMatch = p.adlerianLensTags.length / 7;
      score += lensMatch * 0.32;

      // Pair 匹配 (22%)
      const pairMatch = p.pairTags.filter(pt => pairPatterns.includes(pt)).length / Math.max(pairPatterns.length, 1);
      score += pairMatch * 0.22;

      // Current life task (16%)
      if (p.lifeTaskTags.includes(currentLifeTask)) score += 0.16;

      // Scene 匹配 (10%)
      if (p.contextTags.includes(currentScene)) score += 0.10;

      // 文化/语言 (7%)
      if (cultureRegion && p.cultureRegion.includes(cultureRegion)) score += 0.07;

      // 年代 (5%)
      if (ageGen && p.ageGeneration === ageGen) score += 0.05;

      // Novelty (4%) - 未曝光加分
      if (!exposed.has(p.id)) score += 0.04;

      // Opt-in identity (3%) - 权重 ≤3%
      if (optInIdentity && optInIdentity.length > 0) {
        const idMatch = p.identityBucket.some(id =>
          optInIdentity.some(oi => id.includes(oi) || oi.includes(id))
        );
        if (idMatch) score += 0.03;
      }

      // Editorial (1%) - seed 人物轻微加分
      if (p.id.startsWith('person_seed_')) score += 0.01;

      return { person: p, score };
    });

  scored.sort((a, b) => b.score - a.score);

  return scored.slice(0, limit).map(s => s.person);
}

// 验证人物库完整性
export function validatePeopleCorpus(): {
  total: number;
  publicReady: number;
  seedCount: number;
  lensCoverage: Record<string, number>;
  pairCoverage: Record<string, number>;
  identityGap: string[];
  ready: boolean;
} {
  const publicReady = adlerPeople.filter(p => p.reviewStatus === 'public_ready');
  const seedCount = adlerPeople.filter(p => p.id.startsWith('person_seed_')).length;

  const lensCoverage: Record<string, number> = {};
  ['belonging', 'contribution', 'encouragement', 'life_tasks',
   'goal_orientation', 'private_logic', 'safeguarding_tendencies'].forEach(lens => {
    lensCoverage[lens] = publicReady.filter(p => p.adlerianLensTags.includes(lens)).length;
  });

  const pairCoverage: Record<string, number> = {};
  ['AB', 'AC', 'AD', 'BC', 'BD', 'CD'].forEach(pair => {
    pairCoverage[pair] = publicReady.filter(p => p.pairTags.includes(pair)).length;
  });

  const identityGap = publicReady
    .filter(p => p.identityReviewStatus === 'corpus_gap')
    .slice(0, 10)
    .map(p => p.nameCn);

  const ready = (
    publicReady.length >= 600 &&
    seedCount >= 12 &&
    lensCoverage['belonging'] >= 100 &&
    lensCoverage['contribution'] >= 100 &&
    lensCoverage['encouragement'] >= 100 &&
    lensCoverage['life_tasks'] >= 100 &&
    pairCoverage['AB'] >= 40 &&
    pairCoverage['AC'] >= 40 &&
    pairCoverage['AD'] >= 40 &&
    pairCoverage['BC'] >= 40 &&
    pairCoverage['BD'] >= 40 &&
    pairCoverage['CD'] >= 40
  );

  return {
    total: adlerPeople.length,
    publicReady: publicReady.length,
    seedCount,
    lensCoverage,
    pairCoverage,
    identityGap,
    ready,
  };
}
